<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { Plus, Search } from 'lucide-vue-next';
import { api } from '../api';
import { errorText, patch, post, validPassword } from '../saas';
import { useSessionStore } from '../stores/session';
import '../saas.css';
const roleDialog=ref(false),roleOptions=ref<any[]>([]),roleIds=ref<string[]>([]),roleMember=ref<any>(null);
const session=useSessionStore();const rows=ref<any[]>([]);const organizations=ref<any[]>([]);const loading=ref(false);const saving=ref(false);const error=ref('');const q=ref('');const status=ref('');const dialog=ref(false);const form=reactive({username:'',displayName:'',password:'',roleCode:'CITY_USER',organizationId:''});
const isAdmin=computed(()=>session.user?.roles.some(r=>r.code==='CITY_ADMIN'||r.code.startsWith('CITY_ADMIN_'))??false);
const filtered=computed(()=>rows.value.filter(row=>(!q.value||`${row.username} ${row.displayName} ${row.organization?.name??''}`.toLowerCase().includes(q.value.toLowerCase()))&&(!status.value||row.status===status.value)));
const admin=(row:any)=>(row.roles??[]).some((r:any)=>(r.code??r.role?.code??'').startsWith('CITY_ADMIN'));
async function load(){loading.value=true;error.value='';try{const result=await api<any>('/saas/members');rows.value=Array.isArray(result)?result:result.items??[];if(isAdmin.value){const orgs=await api<any>('/system/organizations');organizations.value=Array.isArray(orgs)?orgs:orgs.items??[];roleOptions.value=(await api<any>('/system/users/options')).roles??[]}}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function open(){Object.assign(form,{username:'',displayName:'',password:'',roleCode:'CITY_USER',organizationId:''});dialog.value=true}
async function create(){if(!form.username.trim()||!form.displayName.trim())return ElMessage.warning('请填写账号和姓名');if(!validPassword(form.password))return ElMessage.warning('密码至少8位，并包含大小写字母、数字和符号');saving.value=true;try{await post('/saas/members',{...form,organizationId:form.organizationId||undefined});dialog.value=false;ElMessage.success('成员已创建');await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
async function change(row:any,action:'status'|'role'){const payload=action==='status'?{status:row.status==='ACTIVE'?'DISABLED':'ACTIVE'}:{roleCode:admin(row)?'CITY_USER':'CITY_ADMIN'};const label=action==='status'?(row.status==='ACTIVE'?'停用':'启用'):(admin(row)?'取消管理员身份':'设为管理员');try{await ElMessageBox.confirm(`确认对 ${row.displayName} 执行“${label}”？权限变更将即时生效。`,'变更成员权限',{type:'warning',confirmButtonText:'确认变更',cancelButtonText:'取消'});saving.value=true;await patch(`/saas/members/${row.id}`,payload);ElMessage.success('成员权限已更新');if(row.id===session.user?.id){session.clear();window.location.assign('/login');return}await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}finally{saving.value=false}}
function openRoles(row:any){roleMember.value=row;roleIds.value=(row.roles??[]).map((role:any)=>role.id);roleDialog.value=true}
async function saveRoles(){if(!roleIds.value.length)return ElMessage.warning('请至少选择一个业务角色');saving.value=true;try{await patch(`/system/users/${roleMember.value.id}`,{roleIds:roleIds.value});roleDialog.value=false;ElMessage.success('业务角色已更新');if(roleMember.value.id===session.user?.id){session.clear();window.location.assign('/login');return}await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
async function transfer(row:any){try{await ElMessageBox.confirm(`将本市管理员职责移交给 ${row.displayName}？完成后将解除您当前的管理员身份。`,'移交管理员',{type:'warning',confirmButtonText:'确认移交',cancelButtonText:'取消'});saving.value=true;await post('/saas/transfer-admin',{targetUserId:row.id});ElMessage.success('管理员职责已移交，请重新登录');session.clear();window.location.assign('/login')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}finally{saving.value=false}}
onMounted(load);

function resetQueryFilters() {
  q.value = '';
  status.value = '';
  load();
}
</script>
<template><div class="saas-page"><h1 class="sr-only">本市成员</h1><QueryPanel :loading="loading" @search="load" @reset="resetQueryFilters">
<QueryField label="关键词" keyword><el-input v-model="q" clearable :prefix-icon="Search" placeholder="搜索账号、姓名或机构" aria-label="搜索成员"/></QueryField>
<QueryField label="状态"><el-select aria-label="状态" v-model="status" clearable placeholder="全部状态"><el-option label="正常" value="ACTIVE"/><el-option label="已停用" value="DISABLED"/></el-select></QueryField>
</QueryPanel>
<ListPanel title="成员列表" :total="error ? undefined : ((filtered ?? []).length)">
<template #actions><el-button v-if="isAdmin" :icon="Plus" type="primary" @click="open">新增成员</el-button></template>
<div v-if="error" class="saas-error" role="alert"><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-table v-else v-loading="loading" :data="filtered" row-key="id" empty-text="没有符合条件的成员"><el-table-column prop="displayName" label="姓名" min-width="140"/><el-table-column prop="username" label="账号" min-width="140"/><el-table-column label="所属机构" min-width="200"><template #default="{row}">{{row.organization?.name??'—'}}</template></el-table-column><el-table-column label="角色" min-width="180"><template #default="{row}"><div class="saas-module-tags"><el-tag v-for="r in row.roles" :key="r.id??r.role?.id" size="small" type="info">{{r.name??r.role?.name}}</el-tag></div></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{row.status==='ACTIVE'?'正常':'已停用'}}</el-tag></template></el-table-column><el-table-column v-if="isAdmin" label="操作" width="110" fixed="right"><template #default="{row}"><el-dropdown trigger="click"><el-button text type="primary">管理</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="openRoles(row)">分配业务角色</el-dropdown-item><el-dropdown-item @click="change(row,'status')">{{row.status==='ACTIVE'?'停用成员':'启用成员'}}</el-dropdown-item><el-dropdown-item @click="change(row,'role')">{{admin(row)?'取消管理员身份':'设为管理员'}}</el-dropdown-item><el-dropdown-item v-if="row.id!==session.user?.id&&row.status==='ACTIVE'" divided @click="transfer(row)">移交管理员职责</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table><p class="saas-subtle">本市须至少保留一位有效管理员。部门与区县在组织机构中维护，业务角色在角色权限中维护。</p>
</ListPanel>
<el-dialog v-model="roleDialog" :title="`分配业务角色 · ${roleMember?.displayName??''}`" width="560" destroy-on-close><p class="saas-subtle">只可授予本市允许委派的角色，不能扩大城市功能和辖区范围。</p><el-checkbox-group v-model="roleIds" style="display:flex;flex-direction:column;align-items:flex-start"><el-checkbox v-for="role in roleOptions" :key="role.id" :value="role.id">{{role.name}}</el-checkbox></el-checkbox-group><template #footer><el-button @click="roleDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRoles">保存角色</el-button></template></el-dialog><el-dialog v-model="dialog" title="新增本市成员" width="550" destroy-on-close><el-form label-position="top"><div class="saas-grid"><el-form-item label="账号" required><el-input v-model="form.username" maxlength="40" autocomplete="off"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.displayName" maxlength="50"/></el-form-item></div><el-form-item label="初始密码" required><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/><p class="saas-subtle">至少8位，包含大小写字母、数字和符号。</p></el-form-item><el-form-item label="角色"><el-select v-model="form.roleCode"><el-option label="市级工作人员" value="CITY_USER"/><el-option label="市级管理员" value="CITY_ADMIN"/></el-select></el-form-item><el-form-item label="所属机构"><el-select v-model="form.organizationId" clearable filterable placeholder="默认本市根机构"><el-option v-for="org in organizations" :key="org.id" :label="org.name" :value="org.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建成员</el-button></template></el-dialog></div></template>
